export {renderSquad} from './manager-squad-ui.js';

function poolFor(c){const own=new Set(managerOwned(c).map(id=>legend(id).personId)),seen=new Set();return (hasSandboxWorld(c)?sandboxMarket(c):isEnglishSandbox(c)?ENGLISH_PLAYERS:LEGENDS).filter(p=>{if(own.has(p.personId)||seen.has(p.personId))return false;seen.add(p.personId);return true;});}
export function renderTransfers(c){
 const s=managerView(c),m=c.management,f=m.filters,pool=poolFor(c),filtered=pool.filter(p=>(f.role==='ALL'||p.role===f.role)&&(!s.transferPosition||s.transferPosition==='ALL'||canPlayPosition(p,s.transferPosition))&&(f.club==='ALL'||p.club===f.club)&&(!f.query||p.name.toLowerCase().includes(f.query.toLowerCase()))&&(!f.affordable||managerReport(c,p.id).fee<=managerAvailable(c))),searching=f.query||f.role!=='ALL'||f.club!=='ALL'||f.affordable||(s.transferPosition&&s.transferPosition!=='ALL')||s.browseAll,searchKey=JSON.stringify([f,s.transferPosition,s.browseAll]),page=Math.min(Math.max(0,s.transferSearch===searchKey?Number(s.transferPage)||0:0),Math.max(0,Math.ceil(filtered.length/12)-1)),display=searching?filtered.slice(page*12,(page+1)*12):filtered.filter(p=>c.careerRulesVersion!==2||recruitmentComparison(c,p).comparable).sort((a,b)=>{const ra=managerReport(c,a.id),rb=managerReport(c,b.id);return Number(rb.fee<=managerAvailable(c))-Number(ra.fee<=managerAvailable(c))||rb.difference-ra.difference;}).slice(0,3),active=m.deals.filter(d=>['club','contract','ready','pending'].includes(d.stage));
 const focused=m.deals.find(d=>d.id===s.deal);if(focused)return card('TRANSFER CONVERSATION',legend(focused.player).name,`${v('Back to transfers','close-deal')}${dealCard(c,focused)}`);
 const founder=c.setup?.custom&&hasSandboxWorld(c)&&c.competition.round===0,nav=tabs([['discover','Find players'],...(c.careerRulesVersion===2?[['offers','Incoming offers']]:[]),['shortlist','Shortlist'],['conversations','Conversations'+(active.length?' · '+active.length:'')],...(founder?[['founder','Founding squad']]:[])],s.transferTab,'transfer-tab');
 if(s.transferTab==='offers'&&c.careerRulesVersion===2)return nav+superOffers(c);
 if(s.transferTab==='founder'&&founder)return nav+card('YOUR FIRST TEAM','Build your club at your pace',`<p>Your original squad can start now. Review the priorities below, enquire for signings without releasing anyone, or keep the squad and recruit later.</p>${renderSquadPlan(c,{compact:true})}${preseasonSuggestions(c)}${v('Find players without releasing anyone','transfer-tab','discover')}${v('Use this squad & prepare','prepare','','primary')}${c.management.market?.version===3?'<details><summary>Replace an original player (optional)</summary>'+foundingBuilder(c)+'</details>':foundingBuilder(c)}`);
 if(s.transferTab==='conversations')return nav+card('CONVERSATIONS','One agreement at a time',m.deals.slice().reverse().map(d=>`<div class="mgr-contract-row"><div><strong>${esc(legend(d.player).name)}</strong><small>${esc(d.kind)} · ${esc(d.stage)} · ${money(c,d.fee)}</small></div>${v('Open conversation','deal',d.id)}</div>`).join('')||'<p>No conversations yet. Find a player to start one.</p>');
 if(s.transferTab==='shortlist')return nav+card('YOUR SHORTLIST','Compare your options',m.shortlist.filter(id=>pool.some(p=>p.id===id)).map(id=>candidate(c,pool.find(p=>p.id===id))).join('')||'<p>Save a player from Find players to compare later.</p>')+comparison(c);
 return nav+recruitmentPanel(c)+card('RECRUITMENT',searching?'Search results':'Three players to consider',`<p>${esc(m.recruitmentPriority||'Compare positional cover and sustainable wages.')} · ${managerWindow(c)?'Transfer window open':'Window closed; agreements may queue'}</p>${form('filters',`<div class="manager-form-grid"><label>Player name<input name="query" value="${esc(f.query)}" placeholder="Search players"></label><label>Natural position<select data-manager-view-select="position" aria-label="Natural position">${['ALL','GK','CB','LB','RB','LWB','RWB','DM','CM','AM','LM','RM','LW','RW','ST','SS'].map(pos=>`<option value="${pos}" ${(s.transferPosition||'ALL')===pos?'selected':''}>${pos==='ALL'?'All positions':pos}</option>`).join('')}</select></label><label>Role group${select('role',['ALL','GK','DEF','MID','FWD'].map(x=>[x,x]),f.role)}</label><details><summary>Club & affordability filters</summary><label>Club${select('club',[['ALL','All clubs'],...[...new Set(pool.map(p=>p.club))].sort().map(x=>[x,x])],f.club)}</label><label><input name="affordable" type="checkbox" ${f.affordable?'checked':''}> Affordable fee</label></details></div>`,'',c,'Search players')}<p class="mgr-result-count">${filtered.length} matching players · ${display.length} shown${searching&&filtered.length?' · page '+(page+1)+' / '+Math.ceil(filtered.length/12):''}</p>${searching?`<div class="mgr-actions">${v('Previous players','transfer-page',page-1,'secondary',page===0?'disabled':'')}${v('Next players','transfer-page',page+1,'secondary',(page+1)*12>=filtered.length?'disabled':'')}</div>`:v('Browse all players','browse-players')}<div class="mgr-candidates">${display.map(p=>candidate(c,p)).join('')||'<p>No matching players. Try another name or position.</p>'}</div><details><summary>Reference coverage & estimates</summary>${usesPounds(c)?intelligenceSummary(c):'<p>Historical ratings and finances are authored game values.</p>'}</details>`)+comparison(c);
}
function candidate(c,p){const r=managerReport(c,p.id),m=c.management,s=managerView(c),fit=c.careerRulesVersion===2?recruitmentComparison(c,p,s.transferPosition||'ALL'):{...r,comparable:true,position:null},fitText=fit.comparable?`${fit.difference>=0?'+':''}${fit.difference} base OVR vs ${esc(fit.starter)}${fit.position?' · '+esc(fit.position):''} · ${esc(fit.role)}`:esc(fit.message);return `<article class="mgr-candidate">${face(p)}<div><span class="eyebrow">${esc(positionLabel(p))} · ${p.rating} OVR</span><h3>${esc(p.name)}</h3><p>${esc(p.club)}</p><p><strong>${money(c,r.fee)}</strong> fee · ${money(c,r.wage)}/week</p><small>${fitText}</small></div><div class="mgr-candidate-actions">${v(s.compare.includes(p.id)?'Remove comparison':'Compare player','compare',p.id)}${b(m.shortlist.includes(p.id)?'Remove shortlist':'Shortlist','shortlist',p.id)}${b('Enquire to buy','enquire',p.id,'buy')}${b('Enquire for loan','enquire',p.id,'loan')}</div><details><summary>Scouting & sourced dossier</summary><p>ATT ${p.attack} · DEF ${p.defense} · CTL ${p.control} · STA ${p.stamina}</p><p>Authored interest ${Math.round(r.interest)}/100 · two-season estimated cost ${money(c,r.cost)}. Asking prices and potential are game estimates.</p>${b('View scouting comparison','report',p.id)}${m.reports.includes(p.id)?`<p>${fitText}</p>`:''}${playerDossier(p,c)}</details></article>`;}
function comparison(c){const pool=poolFor(c),players=managerView(c).compare.map(id=>pool.find(p=>p.id===id)).filter(Boolean);return players.length?card('SIDE BY SIDE','Your recruitment comparison',`<div class="mgr-compare-grid">${players.map(p=>{const r=managerReport(c,p.id),fit=c.careerRulesVersion===2?recruitmentComparison(c,p,managerView(c).transferPosition||'ALL'):{...r,comparable:true};return `<article><h3>${esc(p.name)}</h3><p>${esc(positionLabel(p))} · ${p.rating} OVR</p><dl><dt>Asking fee</dt><dd>${money(c,r.fee)}</dd><dt>Weekly wage</dt><dd>${money(c,r.wage)}</dd><dt>Expected role</dt><dd>${fit.comparable?esc(fit.role):esc(fit.message)}</dd><dt>Two-season estimate</dt><dd>${money(c,r.cost)}</dd></dl>${playerDossier(p,c)}</article>`;}).join('')}</div><p>Compare up to three players. Ratings, interest and potential are Touchline estimates.</p>`):'';}
function dealCard(c,d){
 const active=['club','contract'].includes(d.stage),impact=managerDealImpact(c,d),wage=impact.wage,after=impact.cash,forecast=impact.forecast;
 return `<article class="mgr-deal">${dealProgress(d.stage)}${d.kind==='sell'?renderSaleImpact(c,d.player):''}<p class="mgr-deal-status" role="status">${esc(moneyMessage(c,d.message))}</p><div class="mgr-deal-finance" data-deal-impact><div><span>Fee / signing fee</span><strong data-impact="fee">${money(c,d.fee)}</strong></div><div><span>Your weekly wage</span><strong data-impact="wage">${money(c,wage)}</strong></div><div><span>Cash after fee</span><strong data-impact="cash">${money(c,after)}</strong></div>${forecast!==null?`<div><span>Forecast after agreement</span><strong data-impact="forecast">${money(c,forecast)}</strong></div>`:''}</div><p>${esc(d.kind)} · ${d.years} seasons · ${esc(d.role)}${d.kind==='loan'?' · '+d.share+'% wage contribution':''}</p>${active?form('deal',`<div class="manager-form-grid"><label>Fee / signing fee (£)<input name="fee" type="number" min="0" step="1" value="${moneyInput(c,d.fee)}" required ${d.stage==='contract'?'readonly':''}></label><label>Weekly wage${usesPounds(c)?' (£)':''}<input name="wage" type="number" min="0" step="1" value="${moneyInput(c,d.wage)}" required></label><label>${d.kind==='loan'?'Loan duration':'Contract seasons'}${select('years',d.kind==='loan'?[[1,'Rest of this season'],[2,'Through next season']]:[[1,'1'],[2,'2'],[3,'3']],d.years)}</label><label>Promised role${select('role',[['starter','Starter'],['rotation','Rotation'],['prospect','Prospect']],d.role)}</label>${d.kind==='loan'?'<label>Your wage share %<input name="share" type="number" min="0" max="100" value="'+d.share+'"></label>':''}</div>`,d.id,c,'Submit terms'):d.stage==='ready'?`<p>${managerWindow(c)||d.kind==='renew'?'Registration available now.':'Outside the window: arrival will be queued and fee reserved.'}</p>${b('Confirm agreement','deal-confirm',d.id,'','primary')}`:''}${['club','contract','ready','pending'].includes(d.stage)?b('Withdraw','deal-withdraw',d.id,'','ghost'):''}${['complete','withdrawn','declined','expired'].includes(d.stage)?v('Back to transfers','close-deal','','primary'):''}${playerDossier(legend(d.player),c)}</article>`;
}
function contractRow(c,id){const p=legend(id),s=c.condition[id],world=hasSandboxWorld(c)?worldPlayer(c,id):null;return `<article class="mgr-contract-row ${s.contract<=0?'expired':''}" id="contract-${id}"><div><strong>${esc(p.name)}</strong><small>${world?esc(world.loan?.end||world.contractEnd):s.contract+' matchweeks left'} · ${money(c,s.wage??p.rating*.004)}/week · ${esc(s.promise||'rotation')}${s.loan?' · on loan':''}</small></div><div>${!s.loan?b('Discuss renewal','enquire',id,'renew'):''}${c.bench.includes(id)&&!s.loan?b('Negotiate sale','enquire',id,'sell'):''}${v('Player detail','player',id)}</div></article>`;}
export function renderClub(c){const s=managerView(c),m=c.management,nav=tabs([['overview','Objectives'],['finances','Finances'],['contracts','Contracts'],['ledger','Ledger']],s.clubTab,'club-tab');
 if(s.clubTab==='finances')return nav+card('CLUB FINANCES','Plan the next twelve months',`${sandboxFinancePanel(c)||`<p>Available ${money(c,managerAvailable(c))} · cash ${money(c,c.credits)} · reserved ${money(c,c.credits-managerAvailable(c))}</p><p>Receipts, wages and season grants retain this save’s original economy. Pounds are converted from its saved balances; historical values are authored game estimates.</p>`}<p>Opening balance ${money(c,m.openingBalance)}. Unconfirmed deals and future sale proceeds are excluded.</p>`);
 if(s.clubTab==='contracts')return nav+card('SQUAD CONTRACTS','Keep the group together',`<p>Game terms are shown below. Published references remain in the player dossier.</p>${managerOwned(c).slice().sort((a,b)=>c.condition[a].contract-c.condition[b].contract).map(id=>contractRow(c,id)).join('')}`);
 if(s.clubTab==='ledger')return nav+card('FINANCIAL LEDGER','Every recorded transaction',m.ledger.slice().reverse().map(e=>`<div class="fixture"><span>S${e.season} · MD ${e.round} · ${esc(e.kind)}</span><strong>${e.amount>=0?'+':''}${money(c,e.amount)}</strong><small>${esc(e.note)}</small></div>`).join('')||'<p>Your first transaction is ahead.</p>');
 const rank=standings(c.competition).findIndex(t=>t.id==='user')+1;
 return nav+card('CLUB DIRECTION',m.objective.name,`<div class="mgr-club-objective">${clubBadge(c.name,managerColor(c))}<div><h3>Top ${m.objective.rank}</h3><p>${c.competition.round?'Current league position '+rank:'The season is about to begin'} · board confidence ${c.trust}%</p></div></div><div class="mgr-deal-finance">${Object.entries(m.board||{sporting:65,financial:65,squad:65}).map(([key,n])=>`<div><span>${esc(key)}</span><strong>${Math.round(n)}%</strong></div>`).join('')}</div><p>${esc(m.recruitmentPriority||'Build positional cover and sustainable wages around your strongest team.')}</p>${m.honours.length?'<h3>Club honours</h3>'+m.honours.map(h=>`<p>🏆 S${h.season} · ${esc(h.name)}</p>`).join(''):''}${c.trust<=0?'<p>The board has ended this appointment. Your records are retained.</p>':''}<details><summary>Career options</summary>${action('New manager career','eu-reset-career','','ghost')}</details>`);
}
export function renderSeason(c){const s=managerView(c),nav=tabs([['calendar','Calendar'],['standings','League table'],...(c.statisticsVersion>=1?[['statistics','Player statistics']]:[]),['review','Season reviews']],s.seasonTab,'season-tab');
 const table=`<div class="eu-table-wrap"><table class="league-table"><thead><tr><th>#</th><th>Club</th><th>P</th><th>GD</th><th>Pts</th></tr></thead><tbody>${standings(c.competition).map((t,i)=>`<tr class="${t.id==='user'?'mine':''}"><td>${i+1}</td><td>${esc(t.name)}</td><td>${t.p}</td><td>${t.gf-t.ga}</td><td>${t.pts}</td></tr>`).join('')}</tbody></table></div>`;
 const reviews=c.management.archive.map(a=>`<article class="mgr-season-review"><span class="eyebrow">SEASON ${a.season}</span><h3>League finish: ${a.rank}</h3><p>${esc(a.objective)} · ${a.achieved?'Objective achieved':'Objective missed'}</p><p>Closing balance ${money(c,a.credits)}</p>${a.connectedReview?`<p>Cup: ${esc(a.connectedReview.cupWinner)} · ${a.connectedReview.europeWinner?'Europe: '+esc(a.connectedReview.europeWinner):'Super Cup season'}</p>`:''}${(a.physicalResults||[]).map((r,i)=>action('Replay recorded match · '+r.score.join('–'),'eu-manager-archive',i,'secondary',`data-season="${a.season}"`)).join('')}</article>`).join('')||'<p>Complete a season to record your review.</p>';
 return nav+'<div id="manager-season-panel" role="tabpanel" aria-labelledby="manager-season-tab-'+s.seasonTab+'">'+card('YOUR SEASON',s.seasonTab==='standings'?'The league table':s.seasonTab==='statistics'?'Player statistics':s.seasonTab==='review'?'The season, recorded':'Your calendar',s.seasonTab==='standings'?table:s.seasonTab==='statistics'?superStatistics(c):s.seasonTab==='review'?`${reviews}${seasonComplete(c)?action('Start next season','eu-next-season','','primary'):''}${seasonComplete(c)&&!c.connected&&!isEnglishSandbox(c)&&!hasSandboxWorld(c)?action('Start connected fantasy season','eu-connected-adopt','','secondary'):''}`:schedule(c))+`</div><details class="mgr-season-options"><summary>Season advancement & records</summary><p>Advance statistical fixtures until a decision or the season ends. Completed rounds are saved. No physical replay is invented for fast results.</p>${action('Advance until a decision','eu-career-season','','secondary')}<details><summary>Recorded league fixtures · ${c.competition.results.length}</summary>${c.competition.results.map(r=>`<div class="fixture"><span>${esc(c.competition.teams.find(t=>t.id===r.home)?.name)}</span><b>${r.score.join('–')}</b><span>${esc(c.competition.teams.find(t=>t.id===r.away)?.name)}</span></div>`).join('')}</details><details class="locked-leagues"><summary>Real-league careers · data verification required</summary>${MANAGER_DATASETS.map(d=>`<p><strong>${esc(d.name)}</strong> · ${esc(d.status)}<br>${esc(d.reason)}</p>`).join('')}</details></details>`;
}
function schedule(c){if(c.connected)return connectedSchedulePanel(c);const calendar=hasSandboxWorld(c)?sandboxCalendar(c):fantasyManagerCalendar(c),mine=calendar.fixtures.filter(f=>f.home==='user'||f.away==='user');return `<p>${hasSandboxWorld(c)?'August–May · 38 matchdays · four rest breaks. Windows: 1 August–1 September and 1–31 January.':'Authored weekly fantasy calendar; this save retains its original rules.'}</p><div class="manager-fixture-scroll">${mine.map(f=>{const home=f.home==='user',opponent=c.competition.teams.find(t=>t.id===(home?f.away:f.home));return `<div class="fixture ${f.status==='scheduled'&&f.round===c.competition.round+1?'mine':''}"><span>${displayDate(f.date)}<small> · ${home?'Home':'Away'}</small></span><strong>${esc(opponent?.name)}</strong><span>${f.result?(home?f.result.score:[...f.result.score].reverse()).join('–'):'Upcoming'}</span></div>`;}).join('')}</div><details><summary>Competition rules</summary><p>Win 3 points, draw 1. Ties: goal difference, goals scored, stable club ID. ${hasSandboxWorld(c)?'Fixed membership; league only, no cups or relegation.':'Fantasy competition rules.'}</p></details>`;}
export function managerFormCommand(el){const d=Object.fromEntries(new FormData(el)),type=el.dataset.managerForm,id=el.dataset.id;if(type==='bench')return {type,ids:new FormData(el).getAll('reserve')};if(type==='lineup')return {type,formation:d.formation,xi:Array.from({length:11},(_,i)=>d['xi'+i])};if(type==='tactics')return {type,preset:d.preset,build:d.build,roles:Object.fromEntries(Array.from({length:10},(_,i)=>[i+1,d['role'+(i+1)]]))};if(type==='deal'){const unit=Number(el.dataset.moneyUnit)||1;return {type:'deal-offer',id,...d,fee:Number(d.fee)/unit,wage:Number(d.wage)/unit};}if(type==='filters')return {type,filters:{query:d.query.trim().slice(0,60),role:d.role,club:d.club,affordable:d.affordable==='on'}};return {type,id,...d};}




function preseasonSuggestions(c){const needs=preseasonTargets(c);if(!needs.length)return '';return '<section aria-label="Pre-season shortlist"><h3>Affordable depth conversations</h3><p>Current squad wages, fee reserves and the next fixture’s positional needs shape these estimates. Every signing still needs an agreed contract.</p>'+needs.map(n=>'<div class="mgr-preseason-targets"><h4>'+esc(n.position)+' · rotation cover</h4>'+n.targets.map(({player:p,report:r})=>'<article class="mgr-cover"><div><strong>'+esc(p.name)+'</strong><small>'+p.rating+' OVR · '+money(c,r.fee)+' asking fee · '+money(c,r.wage)+'/week</small></div>'+b('Discuss '+p.name,'enquire',p.id,'buy')+'</article>').join('')+(n.targets.length?'':'<p>No affordable, eligible target passes the current cover and wage-reserve checks. Keep the squad, change the shape or use manual search.</p>')+'</div>').join('')+'</section>';}
